 19	const ZERO = new Decimal(0);
 20	
 21	function refuse(
 22	  code: string,
 23	  message: string,
 24	  diagnostics?: Record<string, unknown>
 25	): V2CoreRefusal {
 26	  return {
 27	    ok: false,
 28	    code: code as V2CoreRefusal['code'],
 29	    stage: 'waterfall',
 30	    message,
 31	    ...(diagnostics ? { diagnostics } : {}),
 32	  };
 33	}
