 35	export interface EntitlementPool {
 36	  readonly dealId: string;
 37	  readonly securityId: string;
 38	  proceedsAvailable: Decimal;
 39	  costBasisRelieved: Decimal;
 40	  gainLoss: Decimal;
 41	}
