 43	export interface DealByDealTierResult {
 44	  readonly kind: string;
 45	  readonly priority: number;
 46	  totalAllocated: Decimal;
 47	  gpShare: Decimal;
 48	  lpShare: Decimal;
 49	  perPartner: Map<string, Decimal>;
 50	}
