 52	export interface DealByDealWaterfallResult {
 53	  readonly ok: true;
 54	  readonly pools: readonly EntitlementPool[];
 55	  readonly tierAllocations: readonly DealByDealTierResult[];
 56	  readonly partnerDistributions: Map<string, Decimal>;
 57	  readonly totalDistributed: Decimal;
 58	}
