 98	function allocateReturnOfCapital(
 99	  available: Decimal,
100	  costBasis: Decimal,
101	  ledgers: Map<string, PartnerLedgerState>
102	): { allocated: Decimal; gpShare: Decimal; lpShare: Decimal; perPartner: Map<string, Decimal> } {
103	  const rocTarget = Decimal.min(available, costBasis);
104	  if (rocTarget.lte(0)) {
105	    return { allocated: ZERO, gpShare: ZERO, lpShare: ZERO, perPartner: new Map() };
106	  }
107	
108	  const partners = Array.from(ledgers.values());
109	  const shares = partners.map((p) => p.settledCapital);
110	  const targetCents = decimalToCents(rocTarget);
111	  const allocCents = apportionCentsLrmFromShares(targetCents, shares);
112	
113	  const perPartner = new Map<string, Decimal>();
114	  let gpTotal = ZERO;
115	  let lpTotal = ZERO;
116	
117	  for (let i = 0; i < partners.length; i++) {
118	    const amount = new Decimal(centsToDecimalString(allocCents[i]!));
119	    perPartner.set(partners[i]!.partnerId, amount);
120	    if (partners[i]!.isGp) {
121	      gpTotal = gpTotal.plus(amount);
122	    } else {
123	      lpTotal = lpTotal.plus(amount);
124	    }
125	  }
126	
127	  return { allocated: rocTarget, gpShare: gpTotal, lpShare: lpTotal, perPartner };
128	}
