130	function allocatePreferredReturn(
131	  available: Decimal,
132	  ledgers: Map<string, PartnerLedgerState>,
133	  gpTreatment: 'pari_passu' | 'excluded'
134	): { allocated: Decimal; gpShare: Decimal; lpShare: Decimal; perPartner: Map<string, Decimal> } {
135	  const eligiblePartners = Array.from(ledgers.values()).filter(
136	    (p) => !(p.isGp && gpTreatment === 'excluded')
137	  );
138	
139	  const totalAccrued = eligiblePartners.reduce((s, p) => s.plus(p.accruedPreference), ZERO);
140	  const prefTarget = Decimal.min(available, totalAccrued);
141	  if (prefTarget.lte(0)) {
142	    return { allocated: ZERO, gpShare: ZERO, lpShare: ZERO, perPartner: new Map() };
143	  }
144	
145	  const shares = eligiblePartners.map((p) => p.accruedPreference);
146	  const targetCents = decimalToCents(prefTarget);
147	  const allocCents = apportionCentsLrmFromShares(targetCents, shares);
148	
149	  const perPartner = new Map<string, Decimal>();
150	  let gpTotal = ZERO;
151	  let lpTotal = ZERO;
152	
153	  for (let i = 0; i < eligiblePartners.length; i++) {
154	    const amount = new Decimal(centsToDecimalString(allocCents[i]!));
155	    perPartner.set(eligiblePartners[i]!.partnerId, amount);
156	    if (eligiblePartners[i]!.isGp) {
157	      gpTotal = gpTotal.plus(amount);
158	    } else {
159	      lpTotal = lpTotal.plus(amount);
160	    }
161	  }
162	
163	  return { allocated: prefTarget, gpShare: gpTotal, lpShare: lpTotal, perPartner };
