166	function apportionBySettledCapital(
167	  amount: Decimal,
168	  partners: readonly PartnerLedgerState[]
169	): Map<string, Decimal> {
170	  if (amount.lte(0) || partners.length === 0) return new Map();
171	
172	  const shares = partners.map((p) => p.settledCapital);
173	  const targetCents = decimalToCents(amount);
174	  const allocCents = apportionCentsLrmFromShares(targetCents, shares);
175	  const result = new Map<string, Decimal>();
176	
177	  for (let i = 0; i < partners.length; i++) {
178	    result.set(partners[i]!.partnerId, new Decimal(centsToDecimalString(allocCents[i]!)));
179	  }
180	  return result;
181	}
