183	function apportionGpLpBuckets(
184	  gpAmount: Decimal,
185	  lpAmount: Decimal,
186	  ledgers: Map<string, PartnerLedgerState>,
187	  tierLabel: 'Catch-up' | 'Carry'
188	): Map<string, Decimal> {
189	  const perPartner = new Map<string, Decimal>();
190	  const partners = Array.from(ledgers.values());
191	  const gpPartners = partners.filter((partner) => partner.isGp);
192	  const lpPartners = partners.filter((partner) => !partner.isGp);
193	
194	  if (gpAmount.gt(0)) {
195	    if (gpPartners.length === 0) {
196	      throw new Error(`${tierLabel} GP bucket invariant violated: no eligible GP partners.`);
197	    }
198	    for (const [id, amount] of apportionBySettledCapital(gpAmount, gpPartners)) {
199	      perPartner.set(id, amount);
200	    }
201	  }
202	
203	  if (lpAmount.gt(0)) {
204	    if (lpPartners.length === 0) {
205	      throw new Error(`${tierLabel} LP bucket invariant violated: no eligible LP partners.`);
206	    }
207	    for (const [id, amount] of apportionBySettledCapital(lpAmount, lpPartners)) {
208	      perPartner.set(id, amount);
209	    }
210	  }
211	
212	  return perPartner;
213	}
