216	  available: Decimal,
217	  gpAllocationRate: Decimal,
218	  gpShare: Decimal,
219	  cumulativeGpProfit: Decimal,
220	  cumulativeLpProfit: Decimal,
221	  ledgers: Map<string, PartnerLedgerState>
222	): {
223	  allocated: Decimal;
224	  gpShareAmount: Decimal;
225	  lpShareAmount: Decimal;
226	  perPartner: Map<string, Decimal>;
227	} {
228	  const allocation = computeGpCatchUpAllocationV2({
229	    available,
230	    cumulativeGpProfit,
231	    cumulativeLpProfit,
232	    terminalGpShare: gpShare,
233	    catchUpGpAllocationRate: gpAllocationRate,
234	  });
235	  const catchUpAllocated = new Decimal(allocation.allocatedTotal);
236	  const gpAmount = new Decimal(allocation.gpAmount);
237	  const lpAmount = new Decimal(allocation.lpAmount);
238	  const perPartner = apportionGpLpBuckets(gpAmount, lpAmount, ledgers, 'Catch-up');
239	
240	  return {
241	    allocated: catchUpAllocated,
242	    gpShareAmount: gpAmount,
243	    lpShareAmount: lpAmount,
244	    perPartner,
245	  };
246	}
