function allocateGpCatchUp(
  available: Decimal,
  gpAllocationRate: Decimal,
  gpShare: Decimal,
  cumulativeGpProfit: Decimal,
  cumulativeLpProfit: Decimal,
  ledgers: Map<string, PartnerLedgerState>
): {
  allocated: Decimal;
  gpShareAmount: Decimal;
  lpShareAmount: Decimal;
  perPartner: Map<string, Decimal>;
} {
  const allocation = computeGpCatchUpAllocationV2({
    available,
    cumulativeGpProfit,
    cumulativeLpProfit,
    terminalGpShare: gpShare,
    catchUpGpAllocationRate: gpAllocationRate,
  });
  const catchUpAllocated = new Decimal(allocation.allocatedTotal);
  const gpAmount = new Decimal(allocation.gpAmount);
  const lpAmount = new Decimal(allocation.lpAmount);
  const perPartner = apportionGpLpBuckets(gpAmount, lpAmount, ledgers, 'Catch-up');

  return {
    allocated: catchUpAllocated,
    gpShareAmount: gpAmount,
    lpShareAmount: lpAmount,
    perPartner,
  };
}

function allocateCarry(
  available: Decimal,
  gpShareRate: Decimal,
  ledgers: Map<string, PartnerLedgerState>
): {
  allocated: Decimal;
  gpShareAmount: Decimal;
  lpShareAmount: Decimal;
  perPartner: Map<string, Decimal>;
} {
  if (available.lte(0)) {
    return { allocated: ZERO, gpShareAmount: ZERO, lpShareAmount: ZERO, perPartner: new Map() };
  }

  const allocation = splitQuantizedGpLp(available, gpShareRate, available);
  const allocated = new Decimal(allocation.allocatedTotal);
  const gpAmount = new Decimal(allocation.gpAmount);
  const lpAmount = new Decimal(allocation.lpAmount);
  const perPartner = apportionGpLpBuckets(gpAmount, lpAmount, ledgers, 'Carry');

  return { allocated, gpShareAmount: gpAmount, lpShareAmount: lpAmount, perPartner };
}

export function runDealByDealWaterfall(
  input: NormalizedInternalEconomicsInputV2,
  state: EventStreamState
): DealByDealResult {
  const pools = buildEntitlementPools(state);
  const policy = input.waterfallPolicy;

  const carryTier = policy.find((t) => t.kind === 'carry') as
    (WaterfallTierV2 & { kind: 'carry' }) | undefined;
  if (!carryTier) {
    return { ok: false, refusal: refuse('INVALID_TIER_POLICY', 'Carry tier is required.') };
  }
  const gpShareRate = new Decimal(carryTier.gpShare);

  const hasCatchUpTier = policy.some((tier) => tier.kind === 'gp_catch_up');
  if (hasCatchUpTier) {
    const openingProfitDecomposition = input.openingState.profitDecomposition;
    const hasOpeningProfitHistory = [
      openingProfitDecomposition.openingCumulativePreferredPaid,
      openingProfitDecomposition.openingCumulativeGpProfitDistributions,
      openingProfitDecomposition.openingCumulativeLpProfitDistributions,
    ].some((amount) => !new Decimal(amount).isZero());

    if (hasOpeningProfitHistory) {
      throw new Error(
        'Deal-by-deal waterfall cannot consume nonzero scalar opening profit-decomposition history with gp_catch_up.'
      );
    }
  }

  const tierResults: DealByDealTierResult[] = [];
  const partnerDistributions = new Map<string, Decimal>();
  for (const [, ledger] of state.partnerLedgers) {
    partnerDistributions.set(ledger.partnerId, ZERO);
  }

  let totalDistributed = ZERO;

  for (const pool of pools) {
    if (pool.proceedsAvailable.lte(0)) continue;

    let remaining = pool.proceedsAvailable;
    let cumulativeGpProfit = ZERO;
    let cumulativeLpProfit = ZERO;

    for (const tier of policy) {
      if (remaining.lte(0)) break;

      let result: DealByDealTierResult;

      switch (tier.kind) {
        case 'return_of_capital': {
          const roc = allocateReturnOfCapital(
            remaining,
            pool.costBasisRelieved,
            state.partnerLedgers
          );
          remaining = remaining.minus(roc.allocated);
          result = {
            kind: 'return_of_capital',
            priority: tier.priority,
            totalAllocated: roc.allocated,
            gpShare: roc.gpShare,
            lpShare: roc.lpShare,
            perPartner: roc.perPartner,
          };
          break;
        }

        case 'preferred_return': {
          const pref = allocatePreferredReturn(
            remaining,
            state.partnerLedgers,
            input.gpCashPreferredReturnTreatment
          );
          remaining = remaining.minus(pref.allocated);
          result = {
            kind: 'preferred_return',
            priority: tier.priority,
            totalAllocated: pref.allocated,
            gpShare: pref.gpShare,
            lpShare: pref.lpShare,
            perPartner: pref.perPartner,
          };
          break;
        }

        case 'gp_catch_up': {
          const catchUp = allocateGpCatchUp(
            remaining,
            new Decimal(tier.gpAllocationRate),
            gpShareRate,
            cumulativeGpProfit,
            cumulativeLpProfit,
            state.partnerLedgers
          );
          remaining = remaining.minus(catchUp.allocated);
          result = {
            kind: 'gp_catch_up',
            priority: tier.priority,
            totalAllocated: catchUp.allocated,
            gpShare: catchUp.gpShareAmount,
            lpShare: catchUp.lpShareAmount,
            perPartner: catchUp.perPartner,
          };
          break;
        }

        case 'carry': {
          const carry = allocateCarry(remaining, gpShareRate, state.partnerLedgers);
          remaining = remaining.minus(carry.allocated);
          result = {
            kind: 'carry',
            priority: tier.priority,
            totalAllocated: carry.allocated,
            gpShare: carry.gpShareAmount,
            lpShare: carry.lpShareAmount,
            perPartner: carry.perPartner,
          };
          break;
        }
      }

      if (tier.kind !== 'return_of_capital') {
        cumulativeGpProfit = cumulativeGpProfit.plus(result.gpShare);
        cumulativeLpProfit = cumulativeLpProfit.plus(result.lpShare);
      }

      for (const [partnerId, amount] of result.perPartner) {
        const current = partnerDistributions.get(partnerId) ?? ZERO;
        partnerDistributions.set(partnerId, current.plus(amount));
      }
      totalDistributed = totalDistributed.plus(result.totalAllocated);
      tierResults.push(result);
    }
  }

  return {
    ok: true,
    pools,
    tierAllocations: tierResults,
    partnerDistributions,
    totalDistributed,
  };
}

import { Decimal } from '../../../lib/decimal-config';

const MONEY_SCALE = 6;
const CENTS_MULTIPLIER = BigInt(10) ** BigInt(MONEY_SCALE);

export function decimalToCents(value: Decimal): bigint {
  const rounded = value.toDecimalPlaces(MONEY_SCALE, Decimal.ROUND_HALF_UP);
  const scaled = rounded.mul(new Decimal(10).pow(MONEY_SCALE));
  return BigInt(scaled.toFixed(0));
}

export function decimalToCentsFloor(value: Decimal): bigint {
  const floored = value.toDecimalPlaces(MONEY_SCALE, Decimal.ROUND_FLOOR);
  const scaled = floored.mul(new Decimal(10).pow(MONEY_SCALE));
  return BigInt(scaled.toFixed(0));
}

export function centsToDecimalString(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intPart = abs / CENTS_MULTIPLIER;
  const fracPart = abs % CENTS_MULTIPLIER;
  const fracStr = fracPart.toString().padStart(MONEY_SCALE, '0');
  return `${negative ? '-' : ''}${intPart}.${fracStr}`;
}

export function decimalStringToCents(value: string): bigint {
  return decimalToCents(new Decimal(value));
}

export class LrmConservationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'LrmConservationError';
  }
}

export function apportionCentsLrm(
  targetCents: bigint,
  exactEntitlements: readonly Decimal[]
): readonly bigint[] {
  if (exactEntitlements.length === 0) {
    if (targetCents !== 0n) {
      throw new LrmConservationError('No entitlement bucket can receive remaining cents.');
    }
    return [];
  }

  const allocations = exactEntitlements.map((e) => {
    const floored = e.toDecimalPlaces(0, Decimal.ROUND_FLOOR);
    return BigInt(floored.toFixed(0));
  });

  const allocationTotal = allocations.reduce((s, a) => s + a, 0n);
  let shortfall = targetCents - allocationTotal;

  if (shortfall < 0n) {
    throw new LrmConservationError('Floored exact entitlements exceed target cents.');
  }

  if (shortfall > 0n) {
    const remainderOrder = exactEntitlements
      .map((entitlement, index) => ({
        index,
        remainder: entitlement.minus(new Decimal(allocations[index]!.toString())),
      }))
      .sort((a, b) => b.remainder.comparedTo(a.remainder) || a.index - b.index);

    let cursor = 0;
    while (shortfall > 0n) {
      const winner = remainderOrder[cursor % remainderOrder.length]!;
      allocations[winner.index] = allocations[winner.index]! + 1n;
      shortfall -= 1n;
      cursor += 1;
    }
  }

  const outputTotal = allocations.reduce((s, a) => s + a, 0n);
  if (outputTotal !== targetCents) {
    throw new LrmConservationError('Integer-cent allocations do not conserve target cents.');
  }

  return allocations;
}

export function apportionCentsLrmFromShares(
  targetCents: bigint,
  shares: readonly Decimal[]
): readonly bigint[] {
  const totalShares = shares.reduce((s, v) => s.plus(v), new Decimal(0));
  if (totalShares.isZero()) {
    if (targetCents !== 0n) {
      throw new LrmConservationError('Cannot apportion nonzero cents with zero total shares.');
    }
    return shares.map(() => 0n);
  }
  const targetDecimal = new Decimal(targetCents.toString());
  const exactEntitlements = shares.map((s) => s.div(totalShares).mul(targetDecimal));
  return apportionCentsLrm(targetCents, exactEntitlements);
}
import { Decimal } from '../../../lib/decimal-config';
import {
  apportionCentsLrm,
  centsToDecimalString,
  decimalToCents,
  decimalToCentsFloor,
} from './decimal-cents-v2';

export interface GpCatchUpAllocationV2Input {
  readonly available: Decimal;
  readonly cumulativeGpProfit: Decimal;
  readonly cumulativeLpProfit: Decimal;
  readonly terminalGpShare: Decimal;
  readonly catchUpGpAllocationRate: Decimal;
}

export interface GpCatchUpAllocationV2Result {
  readonly allocatedTotal: string;
  readonly gpAmount: string;
  readonly lpAmount: string;
}

export function splitQuantizedGpLp(
  allocated: Decimal,
  gpShare: Decimal,
  availableCap?: Decimal
): GpCatchUpAllocationV2Result {
  if (allocated.lt(0) || gpShare.lt(0) || gpShare.gt(1)) {
    throw new Error('GP/LP split invariant violated.');
  }

  // HALF_UP quantization of a value that binds at `availableCap` may exceed the
  // cap by half a unit; clamp to the floored cap so we never distribute more
  // than is physically available.
  let allocatedCents = decimalToCents(allocated);
  if (availableCap !== undefined) {
    const capCents = decimalToCentsFloor(availableCap);
    if (allocatedCents > capCents) allocatedCents = capCents;
  }
  const allocatedUnits = new Decimal(allocatedCents.toString());
  const buckets = apportionCentsLrm(allocatedCents, [
    allocatedUnits.mul(gpShare),
    allocatedUnits.mul(new Decimal(1).minus(gpShare)),
  ]);
  const gpCents = buckets[0]!;
  const lpCents = buckets[1]!;

  return {
    allocatedTotal: centsToDecimalString(gpCents + lpCents),
    gpAmount: centsToDecimalString(gpCents),
    lpAmount: centsToDecimalString(lpCents),
  };
}

export function computeGpCatchUpAllocationV2(
  input: GpCatchUpAllocationV2Input
): GpCatchUpAllocationV2Result {
  const {
    available,
    cumulativeGpProfit,
    cumulativeLpProfit,
    terminalGpShare: c,
    catchUpGpAllocationRate: g,
  } = input;

  if (available.lt(0) || !c.gte(0) || !c.lt(g) || !g.lte(1)) {
    throw new Error('Invalid catch-up allocation inputs.');
  }

  const grossCatchUpDue = Decimal.max(
    new Decimal(0),
    c.mul(cumulativeGpProfit.plus(cumulativeLpProfit)).minus(cumulativeGpProfit).div(g.minus(c))
  );
  const allocated = Decimal.min(available, grossCatchUpDue);

  return splitQuantizedGpLp(allocated, g, available);
}

