  6	export function decimalToCents(value: Decimal): bigint {
  7	  const rounded = value.toDecimalPlaces(MONEY_SCALE, Decimal.ROUND_HALF_UP);
  8	  const scaled = rounded.mul(new Decimal(10).pow(MONEY_SCALE));
  9	  return BigInt(scaled.toFixed(0));
 10	}
