 12	export function decimalToCentsFloor(value: Decimal): bigint {
 13	  const floored = value.toDecimalPlaces(MONEY_SCALE, Decimal.ROUND_FLOOR);
 14	  const scaled = floored.mul(new Decimal(10).pow(MONEY_SCALE));
 15	  return BigInt(scaled.toFixed(0));
 16	}
