 18	export function centsToDecimalString(cents: bigint): string {
 19	  const negative = cents < 0n;
 20	  const abs = negative ? -cents : cents;
 21	  const intPart = abs / CENTS_MULTIPLIER;
 22	  const fracPart = abs % CENTS_MULTIPLIER;
 23	  const fracStr = fracPart.toString().padStart(MONEY_SCALE, '0');
 24	  return `${negative ? '-' : ''}${intPart}.${fracStr}`;
 25	}
