 38	export function apportionCentsLrm(
 39	  targetCents: bigint,
 40	  exactEntitlements: readonly Decimal[]
 41	): readonly bigint[] {
 42	  if (exactEntitlements.length === 0) {
 43	    if (targetCents !== 0n) {
 44	      throw new LrmConservationError('No entitlement bucket can receive remaining cents.');
 45	    }
 46	    return [];
 47	  }
 48	
 49	  const allocations = exactEntitlements.map((e) => {
 50	    const floored = e.toDecimalPlaces(0, Decimal.ROUND_FLOOR);
 51	    return BigInt(floored.toFixed(0));
 52	  });
 53	
 54	  const allocationTotal = allocations.reduce((s, a) => s + a, 0n);
 55	  let shortfall = targetCents - allocationTotal;
 56	
 57	  if (shortfall < 0n) {
 58	    throw new LrmConservationError('Floored exact entitlements exceed target cents.');
 59	  }
 60	
 61	  if (shortfall > 0n) {
 62	    const remainderOrder = exactEntitlements
 63	      .map((entitlement, index) => ({
 64	        index,
 65	        remainder: entitlement.minus(new Decimal(allocations[index]!.toString())),
 66	      }))
 67	      .sort((a, b) => b.remainder.comparedTo(a.remainder) || a.index - b.index);
 68	
 69	    let cursor = 0;
 70	    while (shortfall > 0n) {
 71	      const winner = remainderOrder[cursor % remainderOrder.length]!;
 72	      allocations[winner.index] = allocations[winner.index]! + 1n;
 73	      shortfall -= 1n;
 74	      cursor += 1;
 75	    }
 76	  }
 77	
 78	  const outputTotal = allocations.reduce((s, a) => s + a, 0n);
 79	  if (outputTotal !== targetCents) {
 80	    throw new LrmConservationError('Integer-cent allocations do not conserve target cents.');
 81	  }
 82	
 83	  return allocations;
 84	}
