 86	export function apportionCentsLrmFromShares(
 87	  targetCents: bigint,
 88	  shares: readonly Decimal[]
 89	): readonly bigint[] {
 90	  const totalShares = shares.reduce((s, v) => s.plus(v), new Decimal(0));
 91	  if (totalShares.isZero()) {
 92	    if (targetCents !== 0n) {
 93	      throw new LrmConservationError('Cannot apportion nonzero cents with zero total shares.');
 94	    }
 95	    return shares.map(() => 0n);
 96	  }
 97	  const targetDecimal = new Decimal(targetCents.toString());
 98	  const exactEntitlements = shares.map((s) => s.div(totalShares).mul(targetDecimal));
 99	  return apportionCentsLrm(targetCents, exactEntitlements);
100	}

