 63	function buildEntitlementPools(state: EventStreamState): EntitlementPool[] {
 64	  const poolMap = new Map<string, EntitlementPool>();
 65	
 66	  for (const [, lot] of state.investmentLots) {
 67	    const key = `${lot.dealId}:${lot.securityId}`;
 68	    if (!poolMap.has(key)) {
 69	      poolMap.set(key, {
 70	        dealId: lot.dealId,
 71	        securityId: lot.securityId,
 72	        proceedsAvailable: ZERO,
 73	        costBasisRelieved: ZERO,
 74	        gainLoss: ZERO,
 75	      });
 76	    }
 77	    const pool = poolMap.get(key)!;
 78	    pool.costBasisRelieved = pool.costBasisRelieved.plus(lot.relievedAmount);
 79	  }
 80	
 81	  for (const [, lot] of state.cashSourceLots) {
 82	    if (!lot.lotId.startsWith('proceeds:') || !lot.dealId) continue;
 83	    for (const [key, pool] of poolMap) {
 84	      if (key.startsWith(`${lot.dealId}:`)) {
 85	        pool.proceedsAvailable = pool.proceedsAvailable.plus(lot.originalAmount);
 86	        break;
 87	      }
 88	    }
 89	  }
 90	
 91	  for (const [, pool] of poolMap) {
 92	    pool.gainLoss = pool.proceedsAvailable.minus(pool.costBasisRelieved);
 93	  }
 94	
 95	  return Array.from(poolMap.values());
 96	}
