271	export function runDealByDealWaterfall(
272	  input: NormalizedInternalEconomicsInputV2,
273	  state: EventStreamState
274	): DealByDealResult {
275	  const pools = buildEntitlementPools(state);
276	  const policy = input.waterfallPolicy;
277	
278	  const carryTier = policy.find((t) => t.kind === 'carry') as
279	    (WaterfallTierV2 & { kind: 'carry' }) | undefined;
280	  if (!carryTier) {
281	    return { ok: false, refusal: refuse('INVALID_TIER_POLICY', 'Carry tier is required.') };
282	  }
283	  const gpShareRate = new Decimal(carryTier.gpShare);
284	
285	  const hasCatchUpTier = policy.some((tier) => tier.kind === 'gp_catch_up');
286	  if (hasCatchUpTier) {
287	    const openingProfitDecomposition = input.openingState.profitDecomposition;
288	    const hasOpeningProfitHistory = [
289	      openingProfitDecomposition.openingCumulativePreferredPaid,
290	      openingProfitDecomposition.openingCumulativeGpProfitDistributions,
291	      openingProfitDecomposition.openingCumulativeLpProfitDistributions,
292	    ].some((amount) => !new Decimal(amount).isZero());
293	
294	    if (hasOpeningProfitHistory) {
295	      throw new Error(
296	        'Deal-by-deal waterfall cannot consume nonzero scalar opening profit-decomposition history with gp_catch_up.'
297	      );
298	    }
299	  }
300	
301	  const tierResults: DealByDealTierResult[] = [];
302	  const partnerDistributions = new Map<string, Decimal>();
303	  for (const [, ledger] of state.partnerLedgers) {
304	    partnerDistributions.set(ledger.partnerId, ZERO);
305	  }
306	
307	  let totalDistributed = ZERO;
308	
309	  for (const pool of pools) {
310	    if (pool.proceedsAvailable.lte(0)) continue;
311	
312	    let remaining = pool.proceedsAvailable;
313	    let cumulativeGpProfit = ZERO;
314	    let cumulativeLpProfit = ZERO;
315	
316	    for (const tier of policy) {
317	      if (remaining.lte(0)) break;
318	
319	      let result: DealByDealTierResult;
320	
321	      switch (tier.kind) {
322	        case 'return_of_capital': {
323	          const roc = allocateReturnOfCapital(
324	            remaining,
325	            pool.costBasisRelieved,
326	            state.partnerLedgers
327	          );
328	          remaining = remaining.minus(roc.allocated);
329	          result = {
330	            kind: 'return_of_capital',
331	            priority: tier.priority,
332	            totalAllocated: roc.allocated,
333	            gpShare: roc.gpShare,
334	            lpShare: roc.lpShare,
335	            perPartner: roc.perPartner,
336	          };
337	          break;
338	        }
339	
340	        case 'preferred_return': {
341	          const pref = allocatePreferredReturn(
342	            remaining,
343	            state.partnerLedgers,
344	            input.gpCashPreferredReturnTreatment
345	          );
346	          remaining = remaining.minus(pref.allocated);
347	          result = {
348	            kind: 'preferred_return',
349	            priority: tier.priority,
350	            totalAllocated: pref.allocated,
351	            gpShare: pref.gpShare,
352	            lpShare: pref.lpShare,
353	            perPartner: pref.perPartner,
354	          };
355	          break;
356	        }
357	
358	        case 'gp_catch_up': {
359	          const catchUp = allocateGpCatchUp(
360	            remaining,
361	            new Decimal(tier.gpAllocationRate),
362	            gpShareRate,
363	            cumulativeGpProfit,
364	            cumulativeLpProfit,
365	            state.partnerLedgers
366	          );
367	          remaining = remaining.minus(catchUp.allocated);
368	          result = {
369	            kind: 'gp_catch_up',
370	            priority: tier.priority,
371	            totalAllocated: catchUp.allocated,
372	            gpShare: catchUp.gpShareAmount,
373	            lpShare: catchUp.lpShareAmount,
374	            perPartner: catchUp.perPartner,
375	          };
376	          break;
377	        }
378	
379	        case 'carry': {
380	          const carry = allocateCarry(remaining, gpShareRate, state.partnerLedgers);
381	          remaining = remaining.minus(carry.allocated);
382	          result = {
383	            kind: 'carry',
384	            priority: tier.priority,
385	            totalAllocated: carry.allocated,
386	            gpShare: carry.gpShareAmount,
387	            lpShare: carry.lpShareAmount,
388	            perPartner: carry.perPartner,
389	          };
390	          break;
391	        }
392	      }
393	
394	      if (tier.kind !== 'return_of_capital') {
395	        cumulativeGpProfit = cumulativeGpProfit.plus(result.gpShare);
396	        cumulativeLpProfit = cumulativeLpProfit.plus(result.lpShare);
397	      }
398	
399	      for (const [partnerId, amount] of result.perPartner) {
400	        const current = partnerDistributions.get(partnerId) ?? ZERO;
401	        partnerDistributions.set(partnerId, current.plus(amount));
402	      }
403	      totalDistributed = totalDistributed.plus(result.totalAllocated);
404	      tierResults.push(result);
405	    }
406	  }
407	
408	  return {
409	    ok: true,
410	    pools,
411	    tierAllocations: tierResults,
412	    partnerDistributions,
413	    totalDistributed,
414	  };
415	}

