 78	  ledgers: Map<string, PartnerLedgerState>
 79	): { gpShare: Decimal; lpShare: Decimal } {
 80	  let gpShare = ZERO;
 81	  let lpShare = ZERO;
 82	  for (const [partnerId, amount] of perPartner) {
 83	    const ledger = ledgers.get(partnerId);
 84	    if (ledger?.isGp) {
 85	      gpShare = gpShare.plus(amount);
 86	    } else {
 87	      lpShare = lpShare.plus(amount);
