 93	function apportionGpLpBuckets(
 94	  gpAmount: Decimal,
 95	  lpAmount: Decimal,
 96	  partners: readonly PartnerLedgerState[],
 97	  tierLabel: 'Catch-up' | 'Carry'
 98	): Map<string, Decimal> {
 99	  const perPartner = new Map<string, Decimal>();
100	  const gpPartners = partners.filter((partner) => partner.isGp);
101	  const lpPartners = partners.filter((partner) => !partner.isGp);
102	
103	  if (gpAmount.gt(0)) {
104	    if (gpPartners.length === 0) {
105	      throw new Error(`${tierLabel} GP bucket invariant violated: no eligible GP partners.`);
106	    }
107	    for (const [id, amount] of apportionBySettledCapital(gpAmount, gpPartners)) {
108	      perPartner.set(id, amount);
109	    }
110	  }
111	
112	  if (lpAmount.gt(0)) {
113	    if (lpPartners.length === 0) {
114	      throw new Error(`${tierLabel} LP bucket invariant violated: no eligible LP partners.`);
115	    }
116	    for (const [id, amount] of apportionBySettledCapital(lpAmount, lpPartners)) {
117	      perPartner.set(id, amount);
118	    }
119	  }
120	
121	  return perPartner;
