126	  state: EventStreamState
127	): WholeFundResult {
128	  const policy = input.waterfallPolicy;
129	
130	  const carryTier = policy.find((t) => t.kind === 'carry') as
131	    (WaterfallTierV2 & { kind: 'carry' }) | undefined;
132	  if (!carryTier) {
133	    return { ok: false, refusal: refuse('INVALID_TIER_POLICY', 'Carry tier is required.') };
134	  }
135	  const gpShareRate = new Decimal(carryTier.gpShare);
136	
137	  const totalDistributable = computeTotalDistributable(state);
138	  const totalCostBasis = computeTotalCostBasis(state);
139	  const allPartners = Array.from(state.partnerLedgers.values());
140	
141	  let remaining = totalDistributable;
142	  const openingPreferredPaid = new Decimal(
143	    input.openingState.profitDecomposition.openingCumulativePreferredPaid
144	  );
145	  if (
146	    input.gpCashPreferredReturnTreatment === 'pari_passu' &&
147	    !openingPreferredPaid.isZero() &&
148	    policy.some((tier) => tier.kind === 'gp_catch_up')
149	  ) {
150	    throw new Error(
151	      'Whole-fund pari-passu resume with nonzero opening preferred paid requires GP/LP preferred provenance.'
152	    );
153	  }
154	  let cumulativeGpProfit = new Decimal(
155	    input.openingState.profitDecomposition.openingCumulativeGpProfitDistributions
156	  );
157	  let cumulativeLpProfit = openingPreferredPaid.plus(
158	    input.openingState.profitDecomposition.openingCumulativeLpProfitDistributions
159	  );
160	  const tierResults: WholeFundTierResult[] = [];
161	  const partnerDistributions = new Map<string, Decimal>();
162	  for (const p of allPartners) {
163	    partnerDistributions.set(p.partnerId, ZERO);
164	  }
165	
166	  for (const tier of policy) {
167	    if (remaining.lte(0)) break;
168	
169	    let result: WholeFundTierResult;
170	
171	    switch (tier.kind) {
172	      case 'return_of_capital': {
173	        const rocTarget = Decimal.min(remaining, totalCostBasis);
174	        const perPartner = apportionBySettledCapital(rocTarget, allPartners);
175	        const split = gpLpSplit(perPartner, state.partnerLedgers);
176	        remaining = remaining.minus(rocTarget);
177	        result = {
178	          kind: 'return_of_capital',
179	          priority: tier.priority,
180	          totalAllocated: rocTarget,
181	          gpShare: split.gpShare,
182	          lpShare: split.lpShare,
183	          perPartner,
184	        };
185	        break;
186	      }
187	
188	      case 'preferred_return': {
189	        const eligiblePartners = allPartners.filter(
190	          (p) => !(p.isGp && input.gpCashPreferredReturnTreatment === 'excluded')
191	        );
192	        const totalAccrued = eligiblePartners.reduce((s, p) => s.plus(p.accruedPreference), ZERO);
193	        const prefTarget = Decimal.min(remaining, totalAccrued);
194	
195	        if (prefTarget.lte(0)) {
196	          result = {
197	            kind: 'preferred_return',
198	            priority: tier.priority,
199	            totalAllocated: ZERO,
200	            gpShare: ZERO,
201	            lpShare: ZERO,
202	            perPartner: new Map(),
203	          };
204	          break;
205	        }
206	
207	        const shares = eligiblePartners.map((p) => p.accruedPreference);
208	        const targetCents = decimalToCents(prefTarget);
209	        const allocCents = apportionCentsLrmFromShares(targetCents, shares);
210	        const perPartner = new Map<string, Decimal>();
211	        for (let i = 0; i < eligiblePartners.length; i++) {
212	          perPartner.set(
213	            eligiblePartners[i]!.partnerId,
214	            new Decimal(centsToDecimalString(allocCents[i]!))
215	          );
216	        }
217	
218	        const split = gpLpSplit(perPartner, state.partnerLedgers);
219	        remaining = remaining.minus(prefTarget);
220	        result = {
221	          kind: 'preferred_return',
222	          priority: tier.priority,
223	          totalAllocated: prefTarget,
224	          gpShare: split.gpShare,
225	          lpShare: split.lpShare,
226	          perPartner,
227	        };
228	        break;
229	      }
230	
231	      case 'gp_catch_up': {
232	        const gpAllocationRate = new Decimal(tier.gpAllocationRate);
233	        const catchUp = computeGpCatchUpAllocationV2({
234	          available: remaining,
235	          cumulativeGpProfit,
236	          cumulativeLpProfit,
237	          terminalGpShare: gpShareRate,
238	          catchUpGpAllocationRate: gpAllocationRate,
239	        });
240	        const catchUpAllocated = new Decimal(catchUp.allocatedTotal);
241	        const gpAmount = new Decimal(catchUp.gpAmount);
242	        const lpAmount = new Decimal(catchUp.lpAmount);
243	        const perPartner = apportionGpLpBuckets(gpAmount, lpAmount, allPartners, 'Catch-up');
244	
245	        remaining = remaining.minus(catchUpAllocated);
246	        result = {
247	          kind: 'gp_catch_up',
248	          priority: tier.priority,
249	          totalAllocated: catchUpAllocated,
250	          gpShare: gpAmount,
251	          lpShare: lpAmount,
252	          perPartner,
253	        };
254	        break;
255	      }
256	
257	      case 'carry': {
258	        if (remaining.lte(0)) {
259	          result = {
260	            kind: 'carry',
261	            priority: tier.priority,
262	            totalAllocated: ZERO,
263	            gpShare: ZERO,
264	            lpShare: ZERO,
265	            perPartner: new Map(),
266	          };
267	          break;
268	        }
269	
270	        const carry = splitQuantizedGpLp(remaining, gpShareRate, remaining);
271	        const allocated = new Decimal(carry.allocatedTotal);
272	        const gpAmount = new Decimal(carry.gpAmount);
273	        const lpAmount = new Decimal(carry.lpAmount);
274	        const perPartner = apportionGpLpBuckets(gpAmount, lpAmount, allPartners, 'Carry');
275	
276	        remaining = remaining.minus(allocated);
277	        result = {
278	          kind: 'carry',
279	          priority: tier.priority,
280	          totalAllocated: allocated,
281	          gpShare: gpAmount,
282	          lpShare: lpAmount,
283	          perPartner,
284	        };
285	        break;
286	      }
287	    }
288	
289	    if (tier.kind !== 'return_of_capital') {
290	      cumulativeGpProfit = cumulativeGpProfit.plus(result.gpShare);
291	      cumulativeLpProfit = cumulativeLpProfit.plus(result.lpShare);
292	    }
293	
294	    for (const [partnerId, amount] of result.perPartner) {
295	      const current = partnerDistributions.get(partnerId) ?? ZERO;
296	      partnerDistributions.set(partnerId, current.plus(amount));
297	    }
298	    tierResults.push(result);
299	  }
300	
301	  const totalDistributed = tierResults.reduce((s, r) => s.plus(r.totalAllocated), ZERO);
302	
303	  return {
304	    ok: true,
305	    tierAllocations: tierResults,
306	    partnerDistributions,
307	    totalDistributed,
308	  };
309	}
310	
311	export function toTierAllocationsV2(results: readonly WholeFundTierResult[]): TierAllocationV2[] {
312	  return results.map((r) => ({
313	    kind: r.kind,
314	    priority: r.priority,
315	    totalAllocated: r.totalAllocated.toFixed(6),
316	    gpShare: r.gpShare.toFixed(6),
317	    lpShare: r.lpShare.toFixed(6),
318	  }));
319	}

