 47	export function buildMonthlySchedule(
 48	  fundEstablishmentDate: string,
 49	  calculationDate: string
 50	): readonly MonthlyPeriod[] {
 51	  const estDate = new Date(fundEstablishmentDate);
 52	  const calcDate = new Date(calculationDate);
 53	
 54	  const estYear = estDate.getUTCFullYear();
 55	  const estMonth = estDate.getUTCMonth() + 1;
 56	  const calcYear = calcDate.getUTCFullYear();
 57	  const calcMonth = calcDate.getUTCMonth() + 1;
 58	
 59	  const periods: MonthlyPeriod[] = [];
 60	  let monthIndex = 0;
 61	
 62	  let year = estYear;
 63	  let month = estMonth;
 64	
 65	  while (year < calcYear || (year === calcYear && month <= calcMonth)) {
 66	    const isFirstMonth = year === estYear && month === estMonth;
 67	    const isLastMonth = year === calcYear && month === calcMonth;
 68	
 69	    const start = isFirstMonth ? fundEstablishmentDate : monthStart(year, month);
 70	
 71	    let end: string;
 72	    if (isLastMonth) {
 73	      end = calculationDate;
 74	    } else {
 75	      end = monthEnd(year, month);
 76	    }
 77	
 78	    const isStub =
 79	      (isFirstMonth && estDate.getUTCDate() !== 1) ||
 80	      (isLastMonth && calcDate.getTime() !== new Date(monthEnd(calcYear, calcMonth)).getTime());
 81	
 82	    periods.push({ periodStart: start, periodEnd: end, monthIndex, isStub });
 83	    monthIndex++;
 84	
 85	    month++;
 86	    if (month > 12) {
 87	      month = 1;
 88	      year++;
 89	    }
 90	  }
 91	
 92	  return periods;
 93	}
