 95	export function computePeriodAccrual(
 96	  unreturnedBase: Decimal,
 97	  priorAccrued: Decimal,
 98	  config: PreferredReturnConfig
 99	): Decimal {
100	  if (unreturnedBase.lte(0)) {
101	    return new Decimal(0);
102	  }
103	
104	  if (config.rateMode === 'simple') {
105	    return unreturnedBase.mul(config.annualRate).div(12);
106	  }
107	
108	  const monthlyRate = config.annualRate.plus(1).pow(new Decimal(1).div(12)).minus(1);
109	  const compoundBase = unreturnedBase.plus(priorAccrued);
110	  return compoundBase.mul(monthlyRate);
111	}
