113	export function computeAccrualPostingsForSchedule(
114	  schedule: readonly MonthlyPeriod[],
115	  config: PreferredReturnConfig,
116	  partnerStates: readonly PartnerAccrualState[],
117	  gpTreatment: 'pari_passu' | 'excluded'
118	): readonly MonthlyAccrualPosting[] {
119	  const postings: MonthlyAccrualPosting[] = [];
120	
121	  const runningAccrued = new Map<string, Decimal>();
122	  for (const ps of partnerStates) {
123	    runningAccrued.set(ps.partnerId, ps.accruedPreference);
124	  }
125	
126	  for (const period of schedule) {
127	    const entries: PartnerAccrualEntry[] = [];
128	    let totalAccrual = new Decimal(0);
129	
130	    for (const ps of partnerStates) {
131	      if (ps.isGp && gpTreatment === 'excluded') {
132	        entries.push({
133	          partnerId: ps.partnerId,
134	          openingBase: ps.unreturnedSettledCashCapital,
135	          periodAccrual: new Decimal(0),
136	          closingAccrued: runningAccrued.get(ps.partnerId)!,
137	        });
138	        continue;
139	      }
140	
141	      const priorAccrued = runningAccrued.get(ps.partnerId)!;
142	      const accrual = computePeriodAccrual(ps.unreturnedSettledCashCapital, priorAccrued, config);
143	
144	      const closingAccrued = priorAccrued.plus(accrual);
145	      runningAccrued.set(ps.partnerId, closingAccrued);
146	
147	      entries.push({
148	        partnerId: ps.partnerId,
149	        openingBase: ps.unreturnedSettledCashCapital,
150	        periodAccrual: accrual,
151	        closingAccrued,
152	      });
153	
154	      totalAccrual = totalAccrual.plus(accrual);
155	    }
156	
157	    postings.push({ period, entries, totalAccrual });
158	  }
159	
160	  return postings;
161	}
