 49	function canonicalize(value: unknown): unknown {
 50	  if (value === null || typeof value !== 'object') {
 51	    return value;
 52	  }
 53	  if (value instanceof Date) {
 54	    return value.toJSON();
 55	  }
 56	  if (Decimal.isDecimal(value)) {
 57	    throw new Error('Decimal values must be formatted as decimal strings before hashing.');
 58	  }
 59	  if (Array.isArray(value)) {
 60	    return value.map(canonicalize);
 61	  }
 62	
 63	  const result: Record<string, unknown> = {};
 64	  for (const key of Object.keys(value as Record<string, unknown>).sort()) {
 65	    const child = (value as Record<string, unknown>)[key];
 66	    if (child !== undefined) {
 67	      result[key] = canonicalize(child);
 68	    }
 69	  }
 70	  return result;
 71	}
